const SUMMARY_OUTRO =
  "Auf den folgenden Seiten sehen Sie Ihre fünf Unternehmungsbereiche, die wichtigsten Stärken und prioritären Handlungsfelder.";

function joinSowie(names) {
  return names.length > 1 ? names.join(" sowie ") : names[0];
}
function joinUnd(names) {
  return names.length > 1 ? names.join(" und ") : names[0];
}

function buildSummary(strengths, weaknesses, overallTier) {
  const t = SUMMARY[overallTier.key];

  // Sonderfall: selbst die stärksten Bereiche liegen noch in "Kritisch" —
  // dann keine Differenzierung behaupten, sondern ehrlich benennen.
  if (tierFor(strengths[0].avg).key === "critical") {
    return [
      t.opener,
      "In allen fünf Unternehmungsbereichen zeigt sich aktuell vergleichbar hoher Handlungsbedarf – differenzierte Stärken sind noch nicht erkennbar.",
      t.closer,
    ];
  }
  // Spiegelbild: selbst der schwächste Bereich ist noch "Exzellent".
  if (tierFor(weaknesses[0].avg).key === "high") {
    return [
      t.opener,
      "Alle fünf Unternehmungsbereiche erreichen durchgehend ein exzellentes Niveau – nennenswerte Schwächen sind aktuell nicht erkennbar.",
      t.closer,
    ];
  }
  return [
    t.opener,
    `${t.strength(joinSowie(strengths.map((s) => s.name)))} ${t.weakness(joinUnd(weaknesses.map((s) => s.name)))}`,
    t.closer,
  ];
}

/* ───────────────────────── Datum / Speicher ────────────────────────────── */

const MONTHS = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"];
const p2 = (n) => String(n).padStart(2, "0");

function standLong(d) {
  return `${d.getDate()}. ${MONTHS[d.getMonth()]} ${d.getFullYear()}, ${p2(d.getHours())}:${p2(d.getMinutes())} Uhr`;
}
function standShort(d) {
  return `${p2(d.getDate())}.${p2(d.getMonth() + 1)}.${d.getFullYear()}, ${p2(d.getHours())}:${p2(d.getMinutes())} Uhr`;
}

// Hybrid-Speicher: nutzt window.storage, falls vorhanden, sonst localStorage.
const storage = (typeof window !== "undefined" && window.storage)
  ? {
      get: (k) => window.storage.get(k, false),
      set: (k, v) => window.storage.set(k, v, false),
      delete: (k) => window.storage.delete(k, false),
    }
  : {
      async get(k) {
        const v = localStorage.getItem(k);
        if (v === null) throw new Error("not found");
        return { key: k, value: v };
      },
      async set(k, v) { localStorage.setItem(k, v); return { key: k, value: v }; },
      async delete(k) { localStorage.removeItem(k); return { key: k, deleted: true }; },
    };

/* ══════════════════════════════ App ═══════════════════════════════════════ */

export default function App() {
  const [stage, setStage] = useState("intro");
  const [company, setCompany] = useState("");
  const [email, setEmail] = useState("");
  const [answers, setAnswers] = useState({});
  const [qi, setQi] = useState(0);
  const [editMode, setEditMode] = useState(false);
  const [resumeAvailable, setResumeAvailable] = useState(false);
  const [resumeInfo, setResumeInfo] = useState("");
  const [reportDate, setReportDate] = useState(null);
  const savedRef = useRef(null);

  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get(PROGRESS_KEY);
        const data = res && res.value ? JSON.parse(res.value) : null;
        if (!data || !data.answers) return;

        const count = Object.keys(data.answers).length;
        const ageDays = data.savedAt
          ? (Date.now() - data.savedAt) / 86400000
          : Infinity; // Entwürfe ohne Zeitstempel stammen aus einer älteren Version

        if (ageDays > PROGRESS_MAX_AGE_DAYS || count < PROGRESS_MIN_ANSWERS) {
          await storage.delete(PROGRESS_KEY).catch(() => {});
          return;
        }
        savedRef.current = data;
        setResumeInfo(`Sie haben bereits ${count} von ${allQuestions.length} Fragen beantwortet.`);
        setResumeAvailable(true);
      } catch (e) { /* kein Entwurf vorhanden */ }
    })();
  }, []);

  useEffect(() => {
    if (stage !== "quiz" && stage !== "review") return;
    if (Object.keys(answers).length === 0) return;
    storage.set(PROGRESS_KEY, JSON.stringify({ company, answers, qi, savedAt: Date.now() })).catch(() => {});
  }, [answers, qi, company, stage]);

  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }, [stage, qi]);

  const current = allQuestions[qi];
  const key = current ? `${current.catId}-${current.qIndex}` : null;

  const catScores = useMemo(() =>
    CATEGORIES.map((c) => {
      const vals = c.questions.map((_, i) => answers[`${c.id}-${i}`]).filter(Boolean);
      const avg = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
      return { ...c, avg, pct: Math.round((avg / 5) * 100) };
    }), [answers]);

  const overallAvg = useMemo(() => {
    const vals = Object.values(answers);
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
  }, [answers]);

  const overallTier = tierFor(overallAvg);
  const overallPct = Math.round((overallAvg / 5) * 100);
  const sorted = [...catScores].sort((a, b) => b.avg - a.avg);
  const strengths = sorted.slice(0, 2);
  const weaknesses = [...sorted].reverse().slice(0, 2);
  const displayName = company.trim() || "Ihr Unternehmen";

  function selectAnswer(v) {
    setAnswers({ ...answers, [key]: v });
  }

  function goNext() {
    if (editMode) { setEditMode(false); setStage("review"); return; }
    if (qi < allQuestions.length - 1) setQi(qi + 1);
    // Die Übersicht ist bewusst keine Pflichtstation mehr: jede zusätzliche
    // Station kostet Teilnehmer. Wer korrigieren will, kommt über den Link
    // auf der Score-Vorschau hin.
    else setStage("preview");
  }

  function goBack() {
    if (editMode) { setEditMode(false); setStage("review"); return; }
    if (qi > 0) setQi(qi - 1);
    else setStage("intro");
  }

  async function reset() {
    setAnswers({}); setQi(0); setEditMode(false); setCompany(""); setEmail("");
    setReportDate(null); setResumeAvailable(false); setStage("intro");
    try { await storage.delete(PROGRESS_KEY); } catch (e) {}
  }

  function openReport() {
    setReportDate(new Date());
    setStage("report");
  }

  const scorePayload = {
    company: company.trim() || null,
    overall: Number(fmt(overallAvg)),
    tier: overallTier.label,
    categories: catScores.map((c) => ({ name: c.name, score: Number(fmt(c.avg)), tier: tierFor(c.avg).label })),
    answers: allQuestions.map((q) => ({ nr: q.nr, kapitel: q.catName, wert: answers[`${q.catId}-${q.qIndex}`] || null })),
  };

  return (
    <div style={styles.page}>
      <style>{globalCss}</style>

      {stage === "intro" && (
        <Intro
          company={company} setCompany={setCompany}
          onStart={() => setStage("quiz")}
          resumeAvailable={resumeAvailable}
          resumeInfo={resumeInfo}
          onResume={() => {
            const s = savedRef.current;
            if (s) { setCompany(s.company || ""); setAnswers(s.answers || {}); setQi(s.qi || 0); }
            setResumeAvailable(false); setStage("quiz");
          }}
          onDiscard={() => { setResumeAvailable(false); storage.delete(PROGRESS_KEY).catch(() => {}); }}
        />
      )}

      {stage === "quiz" && current && (
        <Quiz
          current={current} qi={qi} total={allQuestions.length}
          selected={answers[key]} onSelect={selectAnswer}
          onNext={goNext} onBack={goBack} editMode={editMode}
        />
      )}

      {stage === "review" && (
        <Review
          answers={answers}
          onEdit={(i) => { setQi(i); setEditMode(true); setStage("quiz"); }}
          onConfirm={() => setStage("preview")}
        />
      )}

      {stage === "preview" && (
        <Preview
          displayName={displayName} overallAvg={overallAvg} overallPct={overallPct}
          overallTier={overallTier} onNext={() => setStage("teaser")}
          onReview={() => setStage("review")}
        />
      )}

      {stage === "teaser" && <Teaser onNext={() => setStage("email")} />}

      {stage === "email" && (
        <EmailGate
          email={email} setEmail={setEmail}
          payload={scorePayload}
          onSent={() => setStage("verify")}
        />
      )}

      {stage === "verify" && (
        <Verify email={email} onConfirmed={openReport} />
      )}

      {stage === "report" && (
        <Report
          displayName={displayName} date={reportDate || new Date()}
          catScores={catScores} overallAvg={overallAvg} overallPct={overallPct}
          overallTier={overallTier} strengths={strengths} weaknesses={weaknesses}
          answers={answers} onNext={() => setStage("conversion")}
        />
      )}

      {stage === "conversion" && (
        <Conversion company={company} email={email} onRestart={reset} />
      )}
    </div>
  );
}

