const globalCss = `
  * { -webkit-font-smoothing: antialiased; }
  button:focus-visible, input:focus-visible, textarea:focus-visible, a:focus-visible {
    outline: 2px solid ${BLUE}; outline-offset: 2px;
  }
  input::placeholder, textarea::placeholder { color: #B4B0A4; }

  @media (max-width: 760px) {
    .a4 { width: 100% !important; min-height: auto !important; }
  }

  @media (prefers-reduced-motion: reduce) {
    * { transition: none !important; animation: none !important; }
  }

  /* ── Druck: A4, feste Seitenumbrüche ──
     Dieselbe Vorlage kann später serverseitig (Puppeteer) gerendert werden. */
  @page { size: A4; margin: 0; }

  @media print {
    html, body { background: #FFFFFF !important; margin: 0; padding: 0; }
    .no-print { display: none !important; }
    .dev-only { display: none !important; }

    .a4 {
      width: 210mm !important;
      height: 297mm !important;
      min-height: 297mm !important;
      box-shadow: none !important;
      margin: 0 !important;
      page-break-after: always;
      break-after: page;
      overflow: hidden;
    }
    .a4:last-of-type { page-break-after: auto; break-after: auto; }
  }
`;
